{
    "openapi": "3.0.3",
    "info": {
        "title": "audit3 API",
        "version": "0.1.0"
    },
    "paths": {
        "/api/auth/csrf/": {
            "get": {
                "operationId": "auth_csrf_retrieve",
                "description": "``GET csrf/`` ‚Äî CSRF cookie bootstrap for SPAs (amendment A4).\n\nReturns 204 with the CSRF cookie set; a session-mode SPA calls this once\nbefore its first credentialed POST and sends the cookie's value back in\nthe ``X-CSRFToken`` header. Harmless (and unnecessary) in JWT mode.",
                "tags": [
                    "auth"
                ],
                "security": [
                    {
                        "jwtAuth": []
                    },
                    {
                        "cookieAuth": []
                    },
                    {}
                ],
                "responses": {
                    "200": {
                        "description": "No response body"
                    }
                }
            }
        },
        "/api/auth/email/change/": {
            "post": {
                "operationId": "auth_email_change_create",
                "description": "``POST email/change/`` ``{new_email, current_password}`` ‚Äî start the flow.\n\nAuth plus the current password; the confirmation link is emailed to the\n*new* address (clicking it proves ownership). A taken address is a 400\nhere and re-checked at confirm time (services layer, amendments A7/A9).",
                "tags": [
                    "auth"
                ],
                "requestBody": {
                    "content": {
                        "application/json": {
                            "schema": {
                                "$ref": "#/components/schemas/EmailChangeRequest"
                            }
                        },
                        "application/x-www-form-urlencoded": {
                            "schema": {
                                "$ref": "#/components/schemas/EmailChangeRequest"
                            }
                        },
                        "multipart/form-data": {
                            "schema": {
                                "$ref": "#/components/schemas/EmailChangeRequest"
                            }
                        }
                    },
                    "required": true
                },
                "security": [
                    {
                        "jwtAuth": []
                    },
                    {
                        "cookieAuth": []
                    }
                ],
                "responses": {
                    "200": {
                        "content": {
                            "application/json": {
                                "schema": {
                                    "$ref": "#/components/schemas/EmailChange"
                                }
                            }
                        },
                        "description": ""
                    }
                }
            }
        },
        "/api/auth/email/change/confirm/": {
            "post": {
                "operationId": "auth_email_change_confirm_create",
                "description": "``POST email/change/confirm/`` ``{token}`` ‚Äî finish the email change.\n\nAnonymous on purpose: the emailed link lands on a frontend page without a\nsession. A uniqueness race between request and confirm surfaces as a 400\n(``TokenError(\"invalid\")``), never a 500 (amendment A7).",
                "tags": [
                    "auth"
                ],
                "requestBody": {
                    "content": {
                        "application/json": {
                            "schema": {
                                "$ref": "#/components/schemas/OneTimeTokenRequest"
                            }
                        },
                        "application/x-www-form-urlencoded": {
                            "schema": {

